/// <summary>
/// HSMobileOpsDmfSvc request. Each operation reads only the members it needs.
/// </summary>
[DataContractAttribute]
class HSMobileOpsDmfRequest
{
    str        definitionGroupId;
    str        packageName;
    str        executionId;
    boolean    reExecute;
    str        legalEntityId;
    str        uniqueFileName;

}

